/// <summary>
/// PaffH 24.09.25
/// </summary>
/// <param name = "_formRun">FormRun</param>
/// <returns>NDXBVEMailRequestControlCenterFormI</returns>
private static NDXBVEMailRequestControlCenterFormI formHandler(FormRun _formRun)
{
    NDXBVEMailRequestControlCenterFormI formHandlerReturn;
    if (_formRun is NDXFormHandlerIncludedI)
    {
        NDXFormHandlerIncludedI nDXFormHandlerIncludedI = _formRun as NDXFormHandlerIncludedI;
        NDXFormHandler formHandler = nDXFormHandlerIncludedI.parmFormhandler();
        if (formHandler is NDXBVEMailRequestControlCenterFormI)
        {
            formHandlerReturn = formHandler as NDXBVEMailRequestControlCenterFormI;
        }
    }
    return formHandlerReturn;
}

