/// <summary>
/// PaffH 11.08.25
/// last modified: PaffH 27.08.25
/// contact-name modified
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonNameLookUp), FormControlEventType::Modified),
    SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void ContactPersonNameLookUp_OnModified(FormControl sender, FormControlEventArgs e)
{
    NDXContactPersonLookupResult nDXContactPersonLookupResult = NDXContactPersonLookupResult::instance();
    NDXContactPersonLookupContract nDXContactPersonLookupContract = nDXContactPersonLookupResult.parmContract();
    FormRun formRun = sender.formRun();
    FormDataSource fdsContactPerson = formRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenter, ContactPersonLookup));
    QueryBuildDataSource qbdsContactPerson = fdsContactPerson.queryBuildDataSource();
    QueryBuildRange qbr = SysQuery::findOrCreateRange(qbdsContactPerson, fieldNum(ContactPerson, ContactPersonId));
    qbr.value(nDXContactPersonLookupResult.parmContract().parmStrId());
    Query q = fdsContactPerson.query();
    q.allowCrossCompany(true);
    q.clearCompanyRange();
    q.addCompanyRange(nDXContactPersonLookupContract.parmContactPersonDataAreaId());
    fdsContactPerson.executeQuery();
}

/// <summary>
/// PaffH 11.08.25
/// in Build
/// lookup contact email
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonEmailAddressLookUp), FormControlEventType::Lookup)]
public static void ContactPersonEmailAddressLookUp_OnLookup(FormControl sender, FormControlEventArgs e)
{
    FormRun formRun = sender.formRun();

    FormDataSource fdsContactPerson = formRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenter, ContactPersonLookup));
    ContactPerson contactPerson = fdsContactPerson.cursor();
    FormDataSource fdsNDXBVEMailRequestHeader = formRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenter, NDXBVEMailRequestHeader));
    NDXBVEMailRequestHeader nDXBVEMailRequestHeader = fdsNDXBVEMailRequestHeader.cursor();

    DataAreaId companyFilter = nDXBVEMailRequestHeader.ContactPersonDataAreaId;

    NDXBVEMailRequestControlCenterFormI nDXBVEMailRequestControlCenterFormI = NDXBVEMailRequestControlCenter_frm_EventHandler::formHandler(sender.formRun());
    if (nDXBVEMailRequestControlCenterFormI)
    {
        nDXBVEMailRequestControlCenterFormI.contactPersonFdsSetDefault();
        companyFilter = nDXBVEMailRequestControlCenterFormI.getCompanyFilter();
    }

    FormStringControl ctrlContactPersonId = formRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonIdLookUp));
    FormStringControl ctrlContactPersonEmail = formRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenter, ContactPersonEmailAddressLookUp));

    NDXContactPersonLookupContract contract = NDXContactPersonLookupResult::instance().parmContract();
    contract.initLookUpBy();
    contract.parmLookupByEmail(NoYes::Yes);
    contract.parmContactPersonDataAreaId(companyFilter);
    contract.parmStrEmail(ctrlContactPersonEmail.text());

    FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
    NDXBVEMailRequestControlCenterForm::lookupContactPerson(ctrlContactPersonId, contactPerson.ContactPersonId, ctrlContactPersonEmail);

    ce.CancelSuperCall();
}

