/// <summary>
/// PaffH 12.11.25
/// </summary>
/// <param name="sender">FormDataSource</param>
/// <param name="e">FormDataSourceEventArgs</param>
[FormDataSourceEventHandler(formDataSourceStr(NDXBVEMailRequestControlCenter, NDXBVEMailRequestLine_5), FormDataSourceEventType::DisplayOptionInitialize)
    ,SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void NDXBVEMailRequestLine_5_OnDisplayOptionInitialize(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormDataSourceDisplayOptionInitializeEventArgs eventArgs = e as FormDataSourceDisplayOptionInitializeEventArgs;
    NDXBVEMailRequestLine nDXBVEMailRequestLine = eventArgs.record();

    boolean withError = false;
    if (withError)
    {
        int yellow = WinAPI::RGB2int(255,255,182);
        int red = WinAPI::RGB2int(223,13,13);
        eventArgs.displayOption().textColor(yellow);
        eventArgs.displayOption().backColor(red);
    }
    else
    {
        if (!nDXBVEMailRequestLine.ItemId)
        {
            eventArgs.displayOption().textColor(WinAPI::RGB2int(255,0,0));  // red
        }
        if (nDXBVEMailRequestLine.Deactive == NoYes::Yes)
        {
            eventArgs.displayOption().textColor(WinAPI::RGB2int(160,160,160));  // darkgrey
            eventArgs.displayOption().backColor(WinAPI::RGB2int(192,192,192)); // grey
        }
    }

}

